package com.nutritionplatform.home.controller;
import org.springframework.jdbc.core.simple.JdbcClient; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.*;
@RestController @RequestMapping("/api/v1/home") public class HomeController { private final JdbcClient db; public HomeController(JdbcClient db){this.db=db;} @GetMapping public Map<String,Object> today(Authentication a){UUID u=(UUID)a.getPrincipal(); Integer water=db.sql("SELECT water_ml FROM daily_checkin WHERE user_id=:u AND checkin_date=:d").param("u",u).param("d",LocalDate.now()).query(Integer.class).optional().orElse(0); Integer count=db.sql("SELECT COUNT(*) FROM weight_record WHERE user_id=:u").param("u",u).query(Integer.class).single(); return Map.of("date",LocalDate.now().toString(),"waterMl",water,"hasCheckin",water>0,"weightRecordCount",count,"nextMeal",Map.of("available",false),"dailyTasks",Map.of("completed",water>0?1:0,"total",1));} }
